"use strict";
/**
 * Inactive-by-default device sign-in handoff.
 * No account, school relationship or grade is created here.
 *
 * Each challenge is generated by a native client. The client holds a private
 * PKCE verifier plus an independent eight-digit confirmation code. The system
 * browser receives ONLY a random flow id; after a fresh verified Firebase
 * login, the person manually enters the code shown on their own desktop.
 * A single-use server transaction releases a Firebase custom token only to
 * the client proving possession of the original PKCE verifier.
 */
const {createHash,timingSafeEqual}=require("node:crypto");
const HANDOFF_TTL_MS=5*60*1000;
const MAX_CODE_ATTEMPTS=5;
const FLOW_RE=/^[A-Za-z0-9_-]{43}$/;
const CODE_RE=/^\d{8}$/;
const EXCHANGE_RE=/^[A-Za-z0-9_-]{43}$/;
class NativeHandoffError extends Error{
 constructor(code,message){super(message);this.code=code;this.name="NativeHandoffError";}
}
function refuse(code,message){throw new NativeHandoffError(code,message);}
function digest(value){return createHash("sha256").update(value).digest();}
function digestB64(value){return digest(value).toString("base64url");}
function equalDigest(a,b){
 const aa=Buffer.from(String(a||""),"hex"),bb=Buffer.from(String(b||""),"hex");
 return aa.length===32&&bb.length===32&&timingSafeEqual(aa,bb);
}
function validateFlowId(value){
 if(typeof value!=="string"||!FLOW_RE.test(value))
  refuse("invalid-argument","Invalid device pairing reference.");
 return value;
}
function checkInput(data,action){
 if(!data||typeof data!=="object"||Array.isArray(data)||data.action!==action)
  refuse("invalid-argument","Invalid device sign-in request.");
 return validateFlowId(data.flowId);
}
function createNativeClientHandoffService({db,auth,Timestamp,now=()=>Date.now(),enabled=()=>false}){
 if(!db||!auth||!Timestamp)throw new Error("Native handoff requires verified server dependencies.");
 return async request=>{
  // Keep the callable present but inert until an explicitly reviewed roll-out.
  // There is no deployment-time default that enables credential issuance.
  if(!enabled())refuse("failed-precondition","Native application sign-in is not enabled.");
  const data=request?.data;
  const action=data?.action;
  if(!["begin","authorize","redeem","cancel"].includes(action))
   refuse("invalid-argument","Unsupported native sign-in action.");
  const flowId=checkInput(data,action);
  const ref=db.doc("native_client_handoffs/"+flowId),clock=now();
  if(!Number.isSafeInteger(clock)||clock<0)throw Error("Invalid server clock.");
  if(action==="begin"){
   if(data.clientKind!=="desktop"||!EXCHANGE_RE.test(data.challenge||"")||
      !CODE_RE.test(data.confirmationCode))
    refuse("invalid-argument","Invalid native sign-in challenge.");
   // This is an unauthenticated begin: rollout must keep network-level
   // throttling/rate limits active before enabling production issuance.
   const expiresAtMs=clock+HANDOFF_TTL_MS;
   try{
    await ref.create({
     clientKind:"desktop",challenge:data.challenge,
     confirmationDigest:digest(flowId+"."+data.confirmationCode).toString("hex"),
     status:"waiting",attempts:0,createdAtMs:clock,expiresAtMs,
     expiresAt:Timestamp.fromMillis(expiresAtMs),authorizedUid:null
    });
   }catch(error){
    if(error.code===6||error.code==="already-exists")
     refuse("already-exists","This device pairing request already exists.");
    throw error;
   }
   return {state:"waiting",expiresAtMs};
  }
  if(action==="authorize"){
   const uid=request?.auth?.uid,token=request?.auth?.token;
   if(typeof uid!=="string"||!uid||token?.email_verified!==true||!token.email)
    refuse("unauthenticated","Sign in with a verified Adminerva account.");
   // A durable browser session alone must not approve an unrelated new device.
   const signedInAt=Number(token.auth_time)*1000;
   if(!Number.isFinite(signedInAt)||signedInAt>clock+30000||
      clock-signedInAt>5*60*1000)
    refuse("failed-precondition","Sign in again to approve this device.");
   if(!CODE_RE.test(data.confirmationCode))
    refuse("invalid-argument","Enter the eight-digit code shown in your desktop application.");
   const person=await auth.getUser(uid);
   if(person.disabled||person.emailVerified!==true||
      !person.email||person.email.toLowerCase()!==String(token.email).toLowerCase())
    refuse("permission-denied","This verified account is not available for device sign-in.");
   const outcome=await db.runTransaction(async tx=>{
    const snapshot=await tx.get(ref);
    if(!snapshot.exists)return "not-found";
    const row=snapshot.data();
    if(row.expiresAtMs<=clock)return "expired";
    if(row.status==="locked"||row.attempts>=MAX_CODE_ATTEMPTS)return "locked";
    if(row.status!=="waiting")return "not-pending";
    const match=equalDigest(row.confirmationDigest,
      digest(flowId+"."+data.confirmationCode).toString("hex"));
    if(!match){
     const count=row.attempts+1;
     tx.update(ref,{attempts:count,status:count>=MAX_CODE_ATTEMPTS?"locked":"waiting"});
     return "wrong-code";
    }
    tx.update(ref,{status:"approved",authorizedUid:uid,approvedAtMs:clock});
    return "approved";
   });
   if(outcome==="approved")return {state:"approved"};
   const messages={
    "wrong-code":["permission-denied","That code does not match the desktop application."],
    "locked":["resource-exhausted","Too many incorrect codes. Start a new device sign-in."],
    "expired":["failed-precondition","Device sign-in expired. Start again from your desktop."],
    "not-found":["not-found","Device sign-in request was not found."],
    "not-pending":["failed-precondition","This device request has already been processed."]
   };
   refuse(...(messages[outcome]||["failed-precondition","Device sign-in could not finish."]));
  }
  if(typeof data.verifier!=="string"||!EXCHANGE_RE.test(data.verifier))
   refuse("invalid-argument","Invalid device verifier.");
  // Never store or return the native verifier. SHA256 of the raw random
  // verifier bytes (not its UTF-8 base64url representation) is the challenge.
  const verifierBytes=Buffer.from(data.verifier,"base64url");
  if(verifierBytes.length!==32)
   refuse("invalid-argument","Invalid device verifier.");
  const challenge=digestB64(verifierBytes);
  if(action==="cancel"){
   const state=await db.runTransaction(async tx=>{
    const snapshot=await tx.get(ref);
    if(!snapshot.exists)return "missing";
    const row=snapshot.data();
    if(row.challenge!==challenge)return "invalid";
    if(row.status==="waiting"||row.status==="approved"){
     tx.update(ref,{status:"canceled",canceledAtMs:clock});
     return "canceled";
    }
    return row.status;
   });
   return {state};
  }
  const rowSnapshot=await ref.get();
  if(!rowSnapshot.exists)return {state:"waiting"};
  const row=rowSnapshot.data();
  if(row.expiresAtMs<=clock)return {state:"expired"};
  if(row.challenge!==challenge)
   refuse("permission-denied","This device sign-in belongs to another request.");
  if(row.status==="waiting")return {state:"waiting"};
  if(row.status!=="approved")return {state:"unavailable"};
  const person=await auth.getUser(row.authorizedUid);
  if(person.disabled||person.emailVerified!==true||!person.email)
   refuse("permission-denied","The approving account is no longer eligible.");
  const outcome=await db.runTransaction(async tx=>{
   const snapshot=await tx.get(ref);
   if(!snapshot.exists)return null;
   const current=snapshot.data();
   if(current.status!=="approved"||current.expiresAtMs<=now()||
     current.challenge!==challenge||current.authorizedUid!==person.uid)return null;
   tx.update(ref,{status:"consumed",consumedAtMs:now()});
   return person.uid;
  });
  if(!outcome)return {state:"unavailable"};
  const customToken=await auth.createCustomToken(outcome);
  return {state:"authorized",customToken};
 };
}
module.exports={createNativeClientHandoffService,NativeHandoffError,HANDOFF_TTL_MS};
